use serde::Serialize;
use std::collections::HashMap;
use std::time::{Duration, Instant};
use sysinfo::{Components, Disks, Networks, System};

const MB: f64 = 1024.0 * 1024.0;
const GB: f64 = 1024.0 * MB;

/// One frame's worth of collected data. Also the JSON output shape.
#[derive(Debug, Clone, Serialize)]
pub struct Snapshot {
    pub timestamp: String,
    pub uptime_secs: u64,
    pub cpu: Cpu,
    pub memory: Memory,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub temperature: Option<f32>,
    pub disks: Vec<Disk>,
    pub networks: Vec<Net>,
    /// Top processes by CPU usage and by memory.
    pub processes: Processes,
    pub process_count: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct Processes {
    /// Top processes by CPU usage.
    pub by_cpu: Vec<ProcRow>,
    /// Top processes by resident memory.
    pub by_mem: Vec<ProcRow>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Cpu {
    pub total_pct: f32,
    pub per_core_pct: Vec<f32>,
    pub freq_mhz: u64,
}

#[derive(Debug, Clone, Serialize)]
pub struct Memory {
    pub used_bytes: u64,
    pub total_bytes: u64,
    pub pct: f64,
    pub swap_used_bytes: u64,
    pub swap_total_bytes: u64,
}

#[derive(Debug, Clone, Serialize)]
pub struct Disk {
    pub mount: String,
    pub fs: String,
    pub used_pct: f64,
    pub free_gb: f64,
    pub total_gb: f64,
}

#[derive(Debug, Clone, Serialize)]
pub struct Net {
    pub name: String,
    /// Received bytes per second since last tick.
    pub rx_bps: f64,
    /// Transmitted bytes per second since last tick.
    pub tx_bps: f64,
}

#[derive(Debug, Clone, Serialize)]
pub struct ProcRow {
    pub pid: i32,
    pub name: String,
    pub cpu_pct: f32,
    pub mem_mb: f64,
}

/// Stateful collector holding sysinfo handles plus previous network counters
/// so we can compute per-tick rates instead of lifetime totals.
pub struct Collector {
    sys: System,
    disks: Disks,
    networks: Networks,
    components: Option<Components>,
    prev_net: HashMap<String, (u64, u64)>,
    prev_instant: Instant,
    last_cpu_refresh: Instant,
    top_n: usize,
}

impl Collector {
    pub fn new(top_n: usize) -> Self {
        let mut c = Self {
            sys: System::new_all(),
            disks: Disks::new_with_refreshed_list(),
            networks: Networks::new_with_refreshed_list(),
            components: Components::new_with_refreshed_list().into(),
            prev_net: HashMap::new(),
            prev_instant: Instant::now(),
            last_cpu_refresh: Instant::now(),
            top_n,
        };
        c.sys.refresh_all();
        // First sample of CPU usage is garbage; prime it.
        std::thread::sleep(Duration::from_millis(200));
        c.sys.refresh_cpu_all();
        c.snapshot_network_counters();
        c.prev_instant = Instant::now();
        c.last_cpu_refresh = Instant::now();
        c
    }

    fn snapshot_network_counters(&mut self) {
        self.prev_net.clear();
        for (name, data) in &self.networks {
            self.prev_net.insert(
                name.clone(),
                (data.total_received(), data.total_transmitted()),
            );
        }
    }

    pub fn refresh(&mut self) {
        // sysinfo computes CPU usage as the delta between consecutive CPU
        // refreshes. If they happen back-to-back the delta window is ~0 ms and
        // usage gets reported as a bogus constant 100%. Enforce the minimum
        // interval between CPU refreshes.
        let since_last = self.last_cpu_refresh.elapsed();
        if since_last < sysinfo::MINIMUM_CPU_UPDATE_INTERVAL {
            std::thread::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL - since_last);
        }
        self.sys.refresh_all();
        self.last_cpu_refresh = Instant::now();
        self.networks.refresh(true);
        self.disks.refresh(true);
    }

    pub fn snapshot(&mut self, with_temp: bool) -> Snapshot {
        let elapsed = self.prev_instant.elapsed().as_secs_f64().max(1e-6);

        let cores = self.sys.cpus();
        let total_pct = cores.iter().map(|c| c.cpu_usage()).sum::<f32>() / cores.len() as f32;
        let per_core: Vec<f32> = cores.iter().map(|c| c.cpu_usage()).collect();
        let freq_mhz = cores.first().map(|c| c.frequency()).unwrap_or(0);

        let total_ram = self.sys.total_memory();
        let used_ram = self.sys.used_memory();

        let mut temp: Option<f32> = None;
        if with_temp {
            if let Some(comps) = &mut self.components {
                comps.refresh(true);
                // Prefer anything that looks like a CPU sensor; fall back to hottest.
                for c in comps.iter() {
                    let label = c.label().to_ascii_lowercase();
                    if label.contains("cpu") || label.contains("package") || label.contains("tctl")
                    {
                        temp = c.temperature();
                        break;
                    }
                }
                if temp.is_none() {
                    temp = comps
                        .iter()
                        .filter_map(|c| c.temperature())
                        .reduce(f32::max);
                }
            }
        }

        let mut disks: Vec<Disk> = self
            .disks
            .iter()
            .filter(|d| d.total_space() > 0)
            .map(|d| {
                let total = d.total_space();
                let free = d.available_space();
                Disk {
                    mount: d.mount_point().to_string_lossy().into_owned(),
                    fs: d.file_system().to_string_lossy().into_owned(),
                    used_pct: (total - free) as f64 / total as f64 * 100.0,
                    free_gb: free as f64 / GB,
                    total_gb: total as f64 / GB,
                }
            })
            .collect();
        // Skip tiny/ephemeral mounts and dedupe by mount point.
        disks.retain(|d| d.total_gb > 0.5);
        disks.sort_by(|a, b| a.mount.cmp(&b.mount));
        disks.dedup_by(|a, b| a.mount == b.mount);

        let networks: Vec<Net> = self
            .networks
            .iter()
            .map(|(name, data)| {
                let cur = (data.total_received(), data.total_transmitted());
                let (prx, ptx) = self.prev_net.get(name).copied().unwrap_or(cur);
                Net {
                    name: name.clone(),
                    rx_bps: cur.0.saturating_sub(prx) as f64 / elapsed,
                    tx_bps: cur.1.saturating_sub(ptx) as f64 / elapsed,
                }
            })
            .filter(|n| n.rx_bps > 0.0 || n.tx_bps > 0.0)
            .collect();
        self.snapshot_network_counters();
        self.prev_instant = Instant::now();

        let procs: Vec<ProcRow> = self
            .sys
            .processes()
            .values()
            .map(|p| ProcRow {
                pid: p.pid().as_u32() as i32,
                name: p.name().to_string_lossy().chars().take(24).collect(),
                cpu_pct: p.cpu_usage(),
                mem_mb: p.memory() as f64 / MB,
            })
            .collect();

        let process_count = procs.len();
        let mut by_cpu = procs.clone();
        by_cpu.sort_by(|a, b| {
            b.cpu_pct
                .partial_cmp(&a.cpu_pct)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let mut by_mem = procs;
        by_mem.sort_by(|a, b| {
            b.mem_mb
                .partial_cmp(&a.mem_mb)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        Snapshot {
            timestamp: chrono_now(),
            uptime_secs: System::uptime(),
            cpu: Cpu {
                total_pct,
                per_core_pct: per_core,
                freq_mhz,
            },
            memory: Memory {
                used_bytes: used_ram,
                total_bytes: total_ram,
                pct: used_ram as f64 * 100.0 / total_ram.max(1) as f64,
                swap_used_bytes: self.sys.used_swap(),
                swap_total_bytes: self.sys.total_swap(),
            },
            temperature: match temp {
                Some(t) if t > 0.0 => Some(t),
                _ => None,
            },
            disks,
            networks,
            processes: Processes {
                by_cpu: by_cpu.into_iter().take(self.top_n).collect(),
                by_mem: by_mem.into_iter().take(self.top_n).collect(),
            },
            process_count,
        }
    }
}

/// Current UTC timestamp without external crates.
fn chrono_now() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    format_utc(secs)
}

fn format_utc(secs: u64) -> String {
    let days = secs / 86400;
    let rem = secs % 86400;
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // Civil-from-days algorithm (Howard Hinnant).
    let z = days as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let mo = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if mo <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, mo, d, h, m, s)
}

use crate::config::Config;
use crate::stats::{ProcRow, Snapshot};
use std::io::Write;

/// ANSI color helper; emits nothing when color is disabled.
struct Palette {
    color: bool,
}

impl Palette {
    fn new(on: bool) -> Self {
        Self { color: on }
    }
    fn paint(&self, code: &str, text: &str) -> String {
        if self.color {
            format!("\x1b[{}m{}\x1b[0m", code, text)
        } else {
            text.to_string()
        }
    }
    fn dim(&self, s: &str) -> String {
        self.paint("2", s)
    }
    fn cyan(&self, s: &str) -> String {
        self.paint("36", s)
    }
    fn green(&self, s: &str) -> String {
        self.paint("32", s)
    }
    fn yellow(&self, s: &str) -> String {
        self.paint("33", s)
    }
    fn red(&self, s: &str) -> String {
        self.paint("31", s)
    }
    fn bold(&self, s: &str) -> String {
        self.paint("1", s)
    }

    /// Colorize a percentage string by severity.
    fn sev(&self, p: f64, txt: &str) -> String {
        if !self.color {
            return txt.to_string();
        }
        match p as u64 {
            0..=59 => self.green(txt),
            60..=84 => self.yellow(txt),
            _ => self.red(txt),
        }
    }

    fn pct(&self, p: f64) -> String {
        let txt = format!("{:>5.1}%", p);
        self.sev(p, &txt)
    }

    /// Colorized bar: green -> yellow -> red fill.
    fn bar(&self, p: f64, width: usize) -> String {
        let filled = ((p / 100.0) * width as f64).round() as usize;
        let filled = filled.min(width);
        let glyph = "█".repeat(filled);
        let colored = self.sev(p, &glyph);
        format!("{}{}", colored, "░".repeat(width - filled))
    }
}

fn human_bytes(b: u64) -> String {
    const UNITS: [&str; 6] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut v = b as f64;
    let mut u = 0;
    while v >= 1024.0 && u < UNITS.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    if u == 0 {
        format!("{} {}", b, UNITS[0])
    } else {
        format!("{:.1} {}", v, UNITS[u])
    }
}

fn human_rate(bps: f64) -> String {
    if bps >= 1024.0 * 1024.0 {
        format!("{:.1} MiB/s", bps / 1024.0 / 1024.0)
    } else {
        format!("{:.1} KiB/s", bps / 1024.0)
    }
}

fn fmt_uptime(secs: u64) -> String {
    let d = secs / 86400;
    let h = (secs % 86400) / 3600;
    let m = (secs % 3600) / 60;
    if d > 0 {
        format!("{}d {}h {}m", d, h, m)
    } else {
        format!("{}h {}m", h, m)
    }
}

fn strip_ansi(s: &str) -> usize {
    // Count only visible characters.
    let mut count = 0;
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            for e in chars.by_ref() {
                if e == 'm' {
                    break;
                }
            }
        } else {
            count += 1;
        }
    }
    count
}

fn truncate(s: &str, w: usize) -> String {
    match s.char_indices().nth(w) {
        Some((i, _)) => s[..i].to_string(),
        None => s.to_string(),
    }
}

/// Render one full frame into a single String (double-buffered output:
/// one write per tick means no flicker or tearing).
pub fn render(snap: &Snapshot, cfg: &Config, tick: u64) -> String {
    let p = Palette::new(cfg.color);

    let mut lines: Vec<String> = Vec::new();

    macro_rules! add {
        ($($arg:tt)*) => {
            lines.push(format!($($arg)*))
        };
    }

    // CPU panel
    if cfg.cpu {
        let freq = if snap.cpu.freq_mhz > 0 {
            format!(" @ {:.1} GHz", snap.cpu.freq_mhz as f64 / 1000.0)
        } else {
            String::new()
        };
        add!(
            " CPU   {} {}{}",
            p.bar(snap.cpu.total_pct as f64, cfg.bar_width),
            p.pct(snap.cpu.total_pct as f64),
            p.dim(&freq)
        );
        // Per-core grid, 6 cores per row, globally numbered.
        for (row_i, chunk) in snap.cpu.per_core_pct.chunks(6).enumerate() {
            let cells: Vec<String> = chunk
                .iter()
                .enumerate()
                .map(|(j, c)| format!("c{}{} {:>3.0}", row_i * 6 + j, p.bar(*c as f64, 5), c))
                .collect();
            add!("       {}", cells.join(" "));
        }
    }

    // Memory panel
    if cfg.ram {
        let mem = &snap.memory;
        add!(
            " MEM   {} {}  ({})",
            p.bar(mem.pct, cfg.bar_width),
            p.pct(mem.pct),
            p.dim(&format!(
                "{} / {}",
                human_bytes(mem.used_bytes),
                human_bytes(mem.total_bytes)
            ))
        );
        if mem.swap_total_bytes > 0 {
            let spct = mem.swap_used_bytes as f64 * 100.0 / mem.swap_total_bytes.max(1) as f64;
            add!(
                " SWP   {} {}",
                p.bar(spct, cfg.bar_width),
                p.dim(&format!("{:>7.1}%", spct))
            );
        }
    }

    // Temperature
    if cfg.temp && snap.temperature.is_some() {
        let t = snap.temperature.unwrap();
        let txt = format!("{:.0}°C", t);
        add!(
            " TEMP  {}",
            if t < 70.0 { p.green(&txt) } else { p.red(&txt) }
        );
    }

    // Disk panel
    if cfg.disk {
        for d in snap.disks.iter().take(4) {
            let mount = truncate(d.mount.trim_end_matches(['\\', '/']), 10);
            add!(
                " DSK   {:<10} {} {}  {} free",
                p.dim(&mount),
                p.bar(d.used_pct, cfg.bar_width),
                p.pct(d.used_pct),
                p.dim(&format!("{:.0}G", d.free_gb))
            );
        }
    }

    // Network panel
    if cfg.net {
        if snap.networks.is_empty() {
            add!(" NET   {}", p.dim("(no activity)"));
        } else {
            for n in snap.networks.iter().take(3) {
                add!(
                    " NET   {:<12} ↓ {}  ↑ {}",
                    p.dim(&truncate(&n.name, 12)),
                    p.green(&human_rate(n.rx_bps)),
                    p.yellow(&human_rate(n.tx_bps))
                );
            }
        }
    }

    // Processes panel
    if cfg.proc_panel {
        lines.push(p.dim(&format!(
            "  {:<22}{:>7}{:>7}{:>9}   {:<22}{:>7}{:>7}{:>9}",
            "NAME(CPU)", "PID", "CPU%", "MEM", "NAME(MEM)", "PID", "CPU%", "MEM"
        )));
        let n = cfg.top_n.min(snap.processes.by_cpu.len());
        for i in 0..n {
            add!(
                " {}",
                fmt_proc_pair(snap.processes.by_cpu.get(i), snap.processes.by_mem.get(i),)
            );
        }
    }

    // Footer
    lines.push(format!(
        " up {} · {} procs · {}ms refresh · ctrl+c quit",
        p.dim(&fmt_uptime(snap.uptime_secs)),
        snap.process_count,
        cfg.interval_ms,
    ));

    // Frame assembly: dynamic-width box around content.
    let inner = lines
        .iter()
        .map(|l| strip_ansi(l))
        .max()
        .unwrap_or(20)
        .max("syswatch v".len() + env!("CARGO_PKG_VERSION").len());

    let top_border = p.cyan(&format!("╔{}╗", "═".repeat(inner)));
    let mid_border = p.cyan(&format!("╠{}╣", "═".repeat(inner)));
    let bot_border = p.cyan(&format!("╚{}╝", "═".repeat(inner)));

    let mut out = String::with_capacity(16 * 1024);

    // Move cursor home + clear below; no full-screen clear flash.
    if tick > 0 {
        out.push_str("\x1b[H\x1b[J");
    } else {
        out.push_str("\x1b[?25l"); // hide cursor on first frame
    }

    out.push_str(&top_border);
    out.push('\n');
    out.push_str(&boxed_line(
        &format!(
            "{}{}",
            p.bold(" syswatch"),
            p.dim(&format!(" v{}", env!("CARGO_PKG_VERSION")))
        ),
        inner,
    ));
    out.push_str(&mid_border);
    out.push('\n');
    for l in &lines {
        out.push_str(&boxed_line(l, inner));
        out.push('\n');
    }
    out.push_str(&bot_border);

    out
}

fn boxed_line(content: &str, inner: usize) -> String {
    let visible = strip_ansi(content);
    let pad = inner.saturating_sub(visible);
    format!("║{}{}", content, " ".repeat(pad) + "║")
}

fn fmt_proc_pair(cpu: Option<&ProcRow>, mem: Option<&ProcRow>) -> String {
    let one = |pr: Option<&ProcRow>| match pr {
        None => " ".repeat(47),
        Some(prc) => format!(
            "{:<22}{:>7}{:>7.1}{:>8.0}M",
            truncate(&prc.name, 22),
            prc.pid,
            prc.cpu_pct,
            prc.mem_mb
        ),
    };
    format!("{}   {}", one(cpu), one(mem))
}

// (end of module)

/// Write a frame and flush in one go (single write per tick).
pub fn flush(frame: &str) {
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(frame.as_bytes());
    let _ = lock.flush();
}

/// Restore terminal state (show cursor).
pub fn cleanup() {
    print!("\x1b[?25h");
    let _ = std::io::stdout().flush();
}

