content.text:
use crate::config::Config;
use crate::logging::log_dir;
use crate::stats::{ProcRow, Snapshot};
use std::fs;
use std::io::{self, BufRead, BufReader, Write};
use std::path::PathBuf;

/// ANSI color helper; emits nothing when color is disabled.
struct Palette {
    color: bool,
}

impl Palette {
    fn new(on: bool) -> Self {
        Self { color: on }
    }
    fn paint(&self, code: &str, text: &str) -> String {
        if self.color {
            format!("\x1b[{}m{}\x1b[0m", code, text)
        } else {
            text.to_string()
        }
    }
    fn dim(&self, s: &str) -> String {
        self.paint("2", s)
    }
    fn cyan(&self, s: &str) -> String {
        self.paint("36", s)
    }
    fn green(&self, s: &str) -> String {
        self.paint("32", s)
    }
    fn yellow(&self, s: &str) -> String {
        self.paint("33", s)
    }
    fn red(&self, s: &str) -> String {
        self.paint("31", s)
    }
    fn bold(&self, s: &str) -> String {
        self.paint("1", s)
    }

    /// Colorize a percentage string by severity.
    fn sev(&self, p: f64, txt: &str) -> String {
        if !self.color {
            return txt.to_string();
        }
        match p as u64 {
            0..=59 => self.green(txt),
            60..=84 => self.yellow(txt),
            _ => self.red(txt),
        }
    }

    fn pct(&self, p: f64) -> String {
        let txt = format!("{:>5.1}%", p);
        self.sev(p, &txt)
    }

    /// Colorized bar: green -> yellow -> red fill.
    fn bar(&self, p: f64, width: usize) -> String {
        let filled = ((p / 100.0) * width as f64).round() as usize;
        let filled = filled.min(width);
        let glyph = "█".repeat(filled);
        let colored = self.sev(p, &glyph);
        format!("{}{}", colored, "░".repeat(width - filled))
    }
}

fn human_bytes(b: u64) -> String {
    const UNITS: [&str; 6] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut v = b as f64;
    let mut u = 0;
    while v >= 1024.0 && u < UNITS.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    if u == 0 {
        format!("{} {}", b, UNITS[0])
    } else {
        format!("{:.1} {}", v, UNITS[u])
    }
}

fn human_rate(bps: f64) -> String {
    if bps >= 1024.0 * 1024.0 {
        format!("{:.1} MiB/s", bps / 1024.0 / 1024.0)
    } else {
        format!("{:.1} KiB/s", bps / 1024.0)
    }
}

fn fmt_uptime(secs: u64) -> String {
    let d = secs / 86400;
    let h = (secs % 86400) / 3600;
    let m = (secs % 3600) / 60;
    if d > 0 {
        format!("{}d {}h {}m", d, h, m)
    } else {
        format!("{}h {}m", h, m)
    }
}

fn strip_ansi(s: &str) -> usize {
    // Count only visible characters.
    let mut count = 0;
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            for e in chars.by_ref() {
                if e == 'm' {
                    break;
                }
            }
        } else {
            count += 1;
        }
    }
    count
}

fn truncate(s: &str, w: usize) -> String {
    match s.char_indices().nth(w) {
        Some((i, _)) => s[..i].to_string(),
        None => s.to_string(),
    }
}

#[derive(Debug, Clone)]
pub struct HistoryState {
    pub selected_date: Option<String>, // YYYY-MM-DD, None for today
    pub range: HistoryRange,
}

#[derive(Debug, Clone, Copy)]
pub enum HistoryRange {
    TwentyFourHours,
    SevenDays,
}

/// Render one full frame into a single String (double-buffered output:
/// one write per tick means no flicker or tearing).
pub fn render(snap: &Snapshot, cfg: &Config, tick: u64) -> String {
    let p = Palette::new(cfg.color);

    let mut lines: Vec<String> = Vec::new();

    macro_rules! add {
        ($($arg:tt)*) => {
            lines.push(format!($($arg)*))
        };
    }

    // CPU panel
    if cfg.cpu {
        let freq = if snap.cpu.freq_mhz > 0 {
            format!(" @ {:.1} GHz", snap.cpu.freq_mhz as f64 / 1000.0)
        } else {
            String::new()
        };
        add!(
            " CPU   {} {}{}",
            p.bar(snap.cpu.total_pct as f64, cfg.bar_width),
            p.pct(snap.cpu.total_pct as f64),
            p.dim(&freq)
        );
        // Per-core grid, 6 cores per row, globally numbered.
        for (row_i, chunk) in snap.cpu.per_core_pct.chunks(6).enumerate() {
            let cells: Vec<String> = chunk
                .iter()
                .enumerate()
                .map(|(j, c)| format!("c{}{} {:>3.0}", row_i * 6 + j, p.bar(*c as f64, 5), c))
                .collect();
            add!("       {}", cells.join(" "));
        }
    }

    // Memory panel
    if cfg.ram {
        let mem = &snap.memory;
        add!(
            " MEM   {} {}  ({})",
            p.bar(mem.pct, cfg.bar_width),
            p.pct(mem.pct),
            p.dim(&format!(
                "{} / {}",
                human_bytes(mem.used_bytes),
                human_bytes(mem.total_bytes)
            ))
        );
        if mem.swap_total_bytes > 0 {
            let spct = mem.swap_used_bytes as f64 * 100.0 / mem.swap_total_bytes.max(1) as f64;
            add!(
                " SWP   {} {}",
                p.bar(spct, cfg.bar_width),
                p.dim(&format!("{:>7.1}%", spct))
            );
        }
    }

    // Temperature
    if cfg.temp && snap.temperature.is_some() {
        let t = snap.temperature.unwrap();
        let txt = format!("{:.0}°C", t);
        add!(
            " TEMP  {}",
            if t < 70.0 { p.green(&txt) } else { p.red(&txt) }
        );
    }

    // Disk panel
    if cfg.disk {
        for d in snap.disks.iter().take(4) {
            let mount = truncate(d.mount.trim_end_matches(['\\', '/']), 10);
            add!(
                " DSK   {:<10} {} {}  {} free",
                p.dim(&mount),
                p.bar(d.used_pct, cfg.bar_width),
                p.pct(d.used_pct),
                p.dim(&format!("{:.0}G", d.free_gb))
            );
        }
    }

    // Network panel
    if cfg.net {
        if snap.networks.is_empty() {
            add!(" NET   {}", p.dim("(no activity)"));
        } else {
            for n in snap.networks.iter().take(3) {
                add!(
                    " NET   {:<12} ↓ {}  ↑ {}",
                    p.dim(&truncate(&n.name, 12)),
                    p.green(&human_rate(n.rx_bps)),
                    p.yellow(&human_rate(n.tx_bps))
                );
            }
        }
    }

    // Processes panel
    if cfg.proc_panel {
        lines.push(p.dim(&format!(
            "  {:<22}{:>7}{:>7}{:>9}   {:<22}{:>7}{:>7}{:>9}",
            "NAME(CPU)", "PID", "CPU%", "MEM", "NAME(MEM)", "PID", "CPU%", "MEM"
        )));
        let n = cfg.top_n.min(snap.processes.by_cpu.len());
        for i in 0..n {
            add!(
                " {}",
                fmt_proc_pair(snap.processes.by_cpu.get(i), snap.processes.by_mem.get(i),)
            );
        }
    }

    // Footer
    lines.push(format!(
        " up {} · {} procs · {}ms refresh · ctrl+c quit",
        p.dim(&fmt_uptime(snap.uptime_secs)),
        snap.process_count,
        cfg.interval_ms,
    ));

    // Frame assembly: dynamic-width box around content.
    let inner = lines
        .iter()
        .map(|l| strip_ansi(l))
        .max()
        .unwrap_or(20)
        .max("syswatch v".len() + env!("CARGO_PKG_VERSION").len());

    let top_border = p.cyan(&format!("╔{}╗", "═".repeat(inner)));
    let mid_border = p.cyan(&format!("╠{}╣", "═".repeat(inner)));
    let bot_border = p.cyan(&format!("╚{}╝", "═".repeat(inner)));

    let mut out = String::with_capacity(16 * 1024);

    // Move cursor home + clear below; no full-screen clear flash.
    if tick > 0 {
        out.push_str("\x1b[H\x1b[J");
    } else {
        out.push_str("\x1b[?25l"); // hide cursor on first frame
    }

    out.push_str(&top_border);
    out.push('\n');
    out.push_str(&boxed_line(
        &format!(
            "{}{}",
            p.bold(" syswatch"),
            p.dim(&format!(" v{}", env!("CARGO_PKG_VERSION")))
        ),
        inner,
    ));
    out.push_str(&mid_border);
    out.push('\n');
    for l in &lines {
        out.push_str(&boxed_line(l, inner));
        out.push('\n');
    }
    out.push_str(&bot_border);

    out
}

fn boxed_line(content: &str, inner: usize) -> String {
    let visible = strip_ansi(content);
    let pad = inner.saturating_sub(visible);
    format!("║{}{}", content, " ".repeat(pad) + "║")
}

fn fmt_proc_pair(cpu: Option<&ProcRow>, mem: Option<&ProcRow>) -> String {
    let one = |pr: Option<&ProcRow>| match pr {
        None => " ".repeat(47),
        Some(prc) => format!(
            "{:<22}{:>7}{:>7.1}{:>8.0}M",
            truncate(&prc.name, 22),
            prc.pid,
            prc.cpu_pct,
            prc.mem_mb
        ),
    };
    format!("{}   {}", one(cpu), one(mem))
}

// (end of module)

/// Write a frame and flush in one go (single write per tick).
pub fn flush(frame: &str) {
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(frame.as_bytes());
    let _ = lock.flush();
}

/// Restore terminal state (show cursor).
pub fn cleanup() {
    print!("\x1b[?25h");
    let _ = std::io::stdout().flush();
}

pub fn render_history(_snap: &Snapshot, _cfg: &Config, _tick: u64, history_state: &HistoryState) -> String {
    // Get log directory
    let log_dir = match log_dir() {
        Some(dir) => dir,
        None => {
            return "Error: Unable to determine log directory".to_string();
        }
    };

    // List log files
    let mut files: Vec<PathBuf> = match fs::read_dir(&log_dir) {
        Ok(entries) => entries
            .filter_map(|e| e.ok())
            .filter_map(|e| {
                let path = e.path();
                if path.extension().and_then(|s| s.to_str()) == Some("jsonl") {
                    Some(path)
                } else {
                    None
                }
            })
            .collect(),
        Err(_) => vec![],
    };
    files.sort(); // Sort by name (which is date)

    if files.is_empty() {
        return "No log files found".to_string();
    }

    // Determine which file to use
    let selected_date = history_state.selected_date.as_deref();
    let file_path = if let Some(date) = selected_date {
        let mut path = log_dir.clone();
        path.push(format!("{}.jsonl", date));
        if path.exists() {
            path
        } else {
            // Fallback to today if the selected date file doesn't exist
            // Use the date from the current snapshot to get today's date string
            let today = &_snap.timestamp[..10];
            let mut path = log_dir.clone();
            path.push(format!("{}.jsonl", today));
            path
        }
    } else {
        // Use today
        let today = &_snap.timestamp[..10];
        let mut path = log_dir.clone();
        path.push(format!("{}.jsonl", today));
        path
    };

    // Read the file and parse snapshots
    let mut snaps = Vec::new();
    if let Ok(file) = File::open(&file_path) {
        let reader = BufReader::new(file);
        for line in reader.lines() {
            if let Ok(line) = line {
                if let Ok(snap) = serde_json::from_str::<Snapshot>(&line) {
                    snaps.push(snap);
                }
            }
        }
    }

    if snaps.is_empty() {
        return format!("No data in log file: {}", file_path.display());
    }

    // Determine bucketing parameters based on range
    let (bucket_duration_secs, num_buckets) = match history_state.range {
        HistoryRange::TwentyFourHours => (300.0, 288), // 5 minutes = 300 seconds, 24*60/5 = 288 buckets
        HistoryRange::SevenDays => (3600.0, 168), // 1 hour = 3600 seconds, 7*24 = 168 buckets
    };
    let snapshot_interval_secs = cfg.interval_ms as f64 / 1000.0;
    let snapshots_per_bucket = (bucket_duration_secs / snapshot_interval_secs).round() as usize;
    if snapshots_per_bucket == 0 {
        return format!("Snapshot interval too large for bucketing: {} ms", cfg.interval_ms);
    }

    // We want to show the most recent `num_buckets` buckets.
    // So we need at least `num_buckets * snapshots_per_bucket` snapshots.
    let needed_snaps = num_buckets * snapshots_per_bucket;
    let start_idx = if snaps.len() >= needed_snaps {
        snaps.len() - needed_snaps
    } else {
        0
    };
    let relevant_snaps = &snaps[start_idx..];

    // If we have fewer snapshots than needed, we'll adjust the number of buckets to fit the data.
    let actual_buckets = relevant_snaps.len() / snapshots_per_bucket;
    if actual_buckets == 0 {
        return format!(
            "Not enough data for {} buckets: need at least {} snapshots, have {}",
            num_buckets,
            needed_snaps,
            snaps.len()
        );
    }

    // Bucket the data: compute average cpu.total_pct and memory.pct for each bucket.
    let mut cpu_buckets = Vec::with_capacity(actual_buckets);
    let mut mem_buckets = Vec::with_capacity(actual_buckets);
    for chunk in relevant_snaps.chunks(snapshots_per_bucket) {
        let cpu_sum: f32 = chunk.iter().map(|s| s.cpu.total_pct).sum();
        let mem_sum: f64 = chunk.iter().map(|s| s.memory.pct).sum();
        cpu_buckets.push(cpu_sum / chunk.len() as f32);
        mem_buckets.push(mem_sum / chunk.len() as f64);
    }

    // Now we have the bucketed data. We'll draw sparklines.
    // We'll also need to draw a time axis.

    // We'll create a string that contains the sparklines and axis.
    // We'll use a fixed height for the graph: 3 lines for CPU, 1 blank line, 3 lines for memory, then axis.
    // But we'll make it compact: we'll draw each sparkline as a line of blocks, and then we'll draw a grid?

    // Instead, we'll draw a simple sparkline using the braille unicode block elements for higher resolution?
    // Given the ANSI TUI, we'll stick to the block elements we already use.

    // We'll draw a sparkline for CPU and one for memory, each as a line of characters where the height of the bar is represented by a character from a set.

    // We'll use the following characters for different levels: "▁▂▃▄▅▆▇█" (U+2581 to U+2588) for 1/8 to 8/8.

    // We'll compute the min and max of the bucketed data to scale.

    // But note: CPU and memory are percentages, so we can fix the scale from 0 to 100.

    // We'll fix the scale from 0 to 100 for both.

    // We'll define a function to convert a percentage to a sparkline character.

    fn percent_to_spark(cpu_pct: f32) -> char {
        let index = ((cpu_pct / 100.0) * 8.0).round() as usize;
        match index {
            0 => '▁',
            1 => '▂',
            2 => '▃',
            3 => '▄',
            4 => '▅',
            5 => '▆',
            6 => '▇',
            7 | _ => '█',
        }
    }

    // We'll do the same for memory (f64).

    fn mem_percent_to_spark(mem_pct: f64) -> char {
        let index = ((mem_pct / 100.0) * 8.0).round() as usize;
        match index {
            0 => '▁',
            1 => '▂',
            2 => '▃',
            3 => '▄',
            4 => '▅',
            5 => '▆',
            6 => '▇',
            7 | _ => '█',
        }
    }

    // Now we'll build the sparkline strings.
    let cpu_spark: String = cpu_buckets.iter().map(|v| percent_to_spark(*v)).collect();
    let mem_spark: String = mem_buckets.iter().map(|v| mem_percent_to_spark(*v)).collect();

    // We'll also need to draw the axis with time labels.
    // We'll assume that the first bucket is the oldest and the last is the newest.
    // We'll compute the time offset for each bucket: bucket_index * bucket_duration_secs.
    // We'll then format the time as HH:MM for the tick labels.

    // We'll mark the day boundary (when the day changes) with a special marker, e.g., a tick that is longer or a different character.

    // We'll compute the date and time for each bucket by using the current snapshot's date as a reference and subtracting the bucket offset.

    // We'll parse the current snapshot's timestamp to get a Unix timestamp, then subtract the bucket offset in seconds to get the bucket time.

    // We'll write a helper function to parse the timestamp string into seconds since epoch.

    fn parse_timestamp_to_seconds(timestamp: &str) -> Option<u64> {
        // Parse string like "2026-08-24T08:30:39Z"
        let mut parts = timestamp.split('T');
        let date_part = parts.next()?;
        let time_part = parts.next()?.trim_end_matches('Z');
        let mut date_parts = date_part.split('-');
        let year = date_parts.next()?.parse::<i64>().ok()?;
        let month = date_parts.next()?.parse::<u32>().ok()?;
        let day = date_parts.next()?.parse::<u32>().ok()?;
        let mut time_parts = time_part.split(':');
        let hour = time_parts.next()?.parse::<u64>().ok()?;
        let minute = time_parts.next()?.parse::<u64>().ok()?;
        let second = time_parts.next()?.parse::<u64>().ok()?;

        // Compute days since 1970-01-01 using the algorithm from format_utc in reverse.
        // We'll use the civil_from_days algorithm from Howard Hinnant (inverse of format_utc).
